<!-- Generated by Trae Work -->
<script setup>
/**
 * 通用选项编辑器 (ChoicesEditor)
 *
 * 用于编辑族群等级 / 角色状态 / 境界大阶 这类 { key, label, color, weight, desc }
 * 的选项列表。不依赖后端，数据由上层通过 props 传入并通过事件写回。
 *
 * 【新增：模板导入器】：可以通过 templates prop 传入预置模板。
 *   点击「套用模板」按钮即可一键替换/合并成该模板的数据结构。
 *
 * Props:
 *   - title: 模块标题（如「族群等级」）
 *   - subtitle: 说明文字
 *   - icon: 图标 emoji
 *   - accentColor: 'gold' | 'cyan' | 'violet' | 'emerald' | 'amber'
 *   - items: 当前选项数组 [{ key, label, color, weight, desc? }]
 *   - keyPlaceholder: key 输入框 placeholder
 *   - keyPattern:    允许的正则（默认允许英文/数字/下划线）
 *   - readOnlyKeys:  禁止编辑/删除的 key 集合（用于保护数据库用到的枚举）
 *   - templates:     预置模板列表 [{ key, name, icon, tags, desc?, count, data: [] }]
 *                    （如果不传，则不显示模板导入器）
 *   - getTemplateFn: 根据模板 key 获取完整模板数据的函数 (key) => [{key,label,color,weight,desc}]
 *                    （必传，如果 templates 有值）
 *
 * Events:
 *   - save(items):   列表发生变更时触发，保存到外部 store
 */
import { ref, computed, watch } from 'vue'
import { CHOICE_COLORS, COLOR_OPTIONS } from '@/stores/choices'

const props = defineProps({
  title: { type: String, required: true },
  subtitle: { type: String, default: '' },
  icon: { type: String, default: '⚙' },
  accentColor: {
    type: String,
    default: 'cyan',
    validator: (v) => ['gold', 'cyan', 'violet', 'emerald', 'amber'].includes(v),
  },
  items: { type: Array, required: true },
  keyPlaceholder: { type: String, default: '例：S / E / A / B / C（英文、数字、下划线）' },
  keyPattern: { type: [RegExp, String], default: /^[A-Za-z0-9_]+$/ },
  readOnlyKeys: { type: Array, default: () => [] },
  templates: { type: Array, default: () => [] },
  getTemplateFn: { type: Function, default: null },
})

const emit = defineEmits(['save'])

/* ==================== 主题色 ==================== */
const accentMap = {
  gold:    { primary: '#D4A853', glow: 'rgba(212,168,83,0.35)',  bg: 'rgba(212,168,83,0.08)' },
  cyan:    { primary: '#667EEA', glow: 'rgba(102,126,234,0.35)', bg: 'rgba(102,126,234,0.08)' },
  violet:  { primary: '#B388F0', glow: 'rgba(179,136,240,0.35)', bg: 'rgba(179,136,240,0.08)' },
  emerald: { primary: '#4ADE80', glow: 'rgba(74,222,128,0.35)',  bg: 'rgba(74,222,128,0.08)' },
  amber:   { primary: '#F59E0B', glow: 'rgba(245,158,11,0.35)',  bg: 'rgba(245,158,11,0.08)' },
}
const accent = computed(() => accentMap[props.accentColor] || accentMap.cyan)

/* ==================== 本地数据（双向编辑，最后 save 写回） ==================== */
const localItems = ref([])

watch(
  () => props.items,
  (val) => {
    localItems.value = val.map((x) => ({ ...x }))
  },
  { immediate: true, deep: true }
)

/** 按权重排序后的列表 */
const sortedItems = computed(() =>
  localItems.value.slice().sort((a, b) => (a.weight || 99) - (b.weight || 99))
)

/* ==================== 表单：新增 / 编辑 ==================== */
const modalOpen = ref(false)
const editingIndex = ref(-1)   // -1 表示新增
const form = ref({
  key: '',
  label: '',
  color: 'cyan',
  weight: 50,
  desc: '',
})
const formErrors = ref({})

function openAdd() {
  editingIndex.value = -1
  form.value = { key: '', label: '', color: props.accentColor, weight: 50, desc: '' }
  formErrors.value = {}
  modalOpen.value = true
}

function openEdit(item) {
  editingIndex.value = localItems.value.findIndex((x) => x.key === item.key)
  form.value = {
    key: item.key || '',
    label: item.label || '',
    color: item.color || 'cyan',
    weight: item.weight ?? 50,
    desc: item.desc || '',
  }
  formErrors.value = {}
  modalOpen.value = true
}

function closeModal() {
  modalOpen.value = false
}

function isReadOnly(key) {
  return props.readOnlyKeys && props.readOnlyKeys.includes(key)
}

function validateForm() {
  const errs = {}
  if (!form.value.key) errs.key = '请输入英文标识'
  else if (props.keyPattern && !(new RegExp(props.keyPattern).test(form.value.key))) {
    errs.key = '仅允许英文、数字和下划线'
  } else {
    const dup = localItems.value.find(
      (x, i) => x.key === form.value.key && i !== editingIndex.value
    )
    if (dup) errs.key = '该英文标识已存在'
  }
  if (!form.value.label) errs.label = '请输入显示名称'
  if (form.value.weight === '' || form.value.weight === null || isNaN(Number(form.value.weight))) {
    errs.weight = '请输入数字'
  }
  formErrors.value = errs
  return Object.keys(errs).length === 0
}

function submitForm() {
  if (!validateForm()) return
  const payload = {
    key: form.value.key,
    label: form.value.label,
    color: form.value.color,
    weight: Number(form.value.weight),
    desc: form.value.desc,
  }
  if (editingIndex.value >= 0) {
    const targetIdx = editingIndex.value
    localItems.value[targetIdx] = { ...payload }
  } else {
    localItems.value.push(payload)
  }
  emit('save', localItems.value.slice())
  closeModal()
}

function onDelete(item) {
  if (isReadOnly(item.key)) {
    alert(`该选项「${item.label}」是系统内置值，不能删除，可编辑。`)
    return
  }
  if (!confirm(`确认删除选项「${item.label} (${item.key})」？删除后对应下拉选项将不再出现。`)) return
  localItems.value = localItems.value.filter((x) => x.key !== item.key)
  emit('save', localItems.value.slice())
}

function onMove(item, delta) {
  const sorted = sortedItems.value
  const idx = sorted.findIndex((x) => x.key === item.key)
  const targetIdx = idx + delta
  if (targetIdx < 0 || targetIdx >= sorted.length) return
  const target = sorted[targetIdx]
  const tmpW = item.weight || 99
  const realItem = localItems.value.find((x) => x.key === item.key)
  const realTarget = localItems.value.find((x) => x.key === target.key)
  if (realItem && realTarget) {
    realItem.weight = target.weight || 99
    realTarget.weight = tmpW
  }
  emit('save', localItems.value.slice())
}

/* ==================== 颜色样条渲染 ==================== */
function colorSwatch(c) {
  return CHOICE_COLORS[c] || CHOICE_COLORS.gray
}

/* =========================================================================
 *  模板导入器 Modal
 * ========================================================================= */
const templateModalOpen = ref(false)
const selectedTemplateKey = ref('')
const importMode = ref('merge')  // 'merge' 合并（同 key 覆盖 + 新 key 追加） | 'replace' 整体替换
const templateApplying = ref(false)
const templateLog = ref([])

function openTemplateModal() {
  selectedTemplateKey.value = ''
  importMode.value = 'merge'
  templateLog.value = []
  templateModalOpen.value = true
}
function closeTemplateModal() {
  if (templateApplying.value) return
  templateModalOpen.value = false
}

/** 预览模板内容 */
const templatePreview = computed(() => {
  if (!selectedTemplateKey.value || !props.getTemplateFn) return null
  const list = props.getTemplateFn(selectedTemplateKey.value) || []
  // 按权重/顺序分组
  const groups = {}
  list.forEach((it) => {
    const c = it.color || 'gray'
    if (!groups[c]) groups[c] = []
    groups[c].push(it)
  })
  return { items: list, groups, count: list.length }
})

/** 执行模板套用 */
async function applyTemplate() {
  if (!selectedTemplateKey.value || !props.getTemplateFn) return
  const tplName = props.templates?.find((x) => x.key === selectedTemplateKey.value)?.name || '所选模板'
  const newData = props.getTemplateFn(selectedTemplateKey.value) || []
  if (!newData.length) {
    alert('模板内容为空，请重新选择')
    return
  }

  templateApplying.value = true
  templateLog.value = []
  const push = (type, msg) => templateLog.value.push({ type, msg, time: new Date().toLocaleTimeString() })

  push('info', `开始套用模板「${tplName}」（${newData.length} 项），模式：${importMode.value === 'merge' ? '同 key 覆盖 + 新 key 追加' : '整体替换'}...`)

  let result = []
  let covered = 0
  let added = 0

  if (importMode.value === 'replace') {
    // 整体替换：但保留 readOnlyKeys 中的系统内置项不被删除
    const preserved = localItems.value.filter((x) => isReadOnly(x.key))
    result = [
      ...preserved,
      ...newData,
    ]
    covered = newData.length
    push('info', `整体替换：保留 ${preserved.length} 个系统内置项，载入模板 ${newData.length} 项。`)
  } else {
    // merge 模式
    result = localItems.value.map((x) => ({ ...x }))
    for (const item of newData) {
      const idx = result.findIndex((x) => x.key === item.key)
      if (idx >= 0) {
        // 只读的不能覆盖
        if (isReadOnly(result[idx].key)) {
          push('skip', `跳过内置项「${result[idx].label || result[idx].key}」（系统只读）`)
          continue
        }
        result[idx] = { ...item }
        covered++
        push('update', `覆盖「${item.label} (${item.key})」`)
      } else {
        result.push({ ...item })
        added++
        push('create', `新增「${item.label} (${item.key})」`)
      }
    }
  }

  // 重新校正 weight 顺序
  result.sort((a, b) => (a.weight || 99) - (b.weight || 99))
  result.forEach((it, i) => { if (!it.weight) it.weight = (i + 1) * 10 })

  push('info', `套用完成：覆盖 ${covered} 项，新增 ${added} 项，合计 ${result.length} 项。`)

  localItems.value = result
  emit('save', result.slice())

  templateApplying.value = false
}
</script>

<template>
  <div class="choices-editor">
    <!-- 页头 -->
    <header class="editor-page__header">
      <div>
        <h2 class="editor-page__title" :style="{ color: accent.primary }">
          <span class="title-icon">{{ icon }}</span>{{ title }}
        </h2>
        <p class="editor-page__subtitle" v-if="subtitle">{{ subtitle }}</p>
      </div>
      <div class="header-actions">
        <button
          v-if="templates && templates.length && getTemplateFn"
          class="template-btn"
          @click="openTemplateModal"
          :style="{ borderColor: accent.primary, color: accent.primary }"
        >
          <span class="plus">📜</span>套用模板
        </button>
        <button class="add-btn" @click="openAdd" :style="{ borderColor: accent.primary, color: accent.primary }">
          <span class="plus">+</span>新增选项
        </button>
      </div>
    </header>

    <!-- 列表 -->
    <div class="choices-list">
      <TransitionGroup name="list" tag="div" class="choices-list__inner">
        <div
          v-for="(item, index) in sortedItems"
          :key="item.key"
          class="choice-card"
          :style="{
            borderColor: colorSwatch(item.color).border,
            background: colorSwatch(item.color).bg,
          }"
        >
          <!-- 颜色条 -->
          <div
            class="color-bar"
            :style="{ background: colorSwatch(item.color).text }"
          ></div>

          <!-- 核心信息 -->
          <div class="choice-main">
            <div class="choice-head">
              <div class="choice-label" :style="{ color: colorSwatch(item.color).text }">
                {{ item.label }}
              </div>
              <span class="choice-key mono">{{ item.key }}</span>
            </div>
            <div class="choice-desc" v-if="item.desc">{{ item.desc }}</div>
            <div class="choice-desc choice-desc--empty" v-else>（暂无描述）</div>
          </div>

          <!-- 权重 -->
          <div class="choice-weight" :title="`权重 ${item.weight ?? 99}，越小排序越靠前`">
            <span class="weight-num" :style="{ color: accent.primary }">{{ item.weight ?? 99 }}</span>
            <span class="weight-label">排序权重</span>
          </div>

          <!-- 上下移动 -->
          <div class="choice-moves">
            <button
              class="move-btn"
              :disabled="index === 0"
              @click="onMove(item, -1)"
              title="上移"
            >▲</button>
            <button
              class="move-btn"
              :disabled="index === sortedItems.length - 1"
              @click="onMove(item, 1)"
              title="下移"
            >▼</button>
          </div>

          <!-- 操作按钮 -->
          <div class="choice-actions">
            <button
              class="action-btn action-btn--edit"
              @click="openEdit(item)"
              :style="{ color: accent.primary, borderColor: colorSwatch(item.color).border }"
            >✎ 编辑</button>
            <button
              class="action-btn action-btn--delete"
              :disabled="isReadOnly(item.key)"
              :title="isReadOnly(item.key) ? '系统内置，不可删除' : '删除该选项'"
              @click="onDelete(item)"
            >× 删除</button>
          </div>
        </div>
      </TransitionGroup>

      <div class="choices-empty" v-if="sortedItems.length === 0">
        <span class="empty-icon">📭</span>
        <div class="empty-text">暂无选项，点击右上角「新增选项」创建或「套用模板」一键导入</div>
      </div>
    </div>

    <!-- 内置提示 -->
    <div class="readonly-hint" v-if="readOnlyKeys && readOnlyKeys.length">
      <span class="hint-icon">ℹ</span>
      <span>灰色删除按钮的选项为系统内置值（对应数据库枚举字段），不可删除，但可编辑名称和颜色。</span>
    </div>

    <!-- ============================================================
         模板导入器 Modal
         ============================================================ -->
    <Teleport to="body">
      <div class="modal-mask" v-if="templateModalOpen" @click.self="closeTemplateModal">
        <div class="modal template-modal" :style="{ borderColor: accent.primary, maxWidth: '780px' }">
          <!-- 角装饰 -->
          <div class="modal__corner modal__corner--tl" :style="{ borderColor: accent.primary }"></div>
          <div class="modal__corner modal__corner--tr" :style="{ borderColor: accent.primary }"></div>
          <div class="modal__corner modal__corner--bl" :style="{ borderColor: accent.primary }"></div>
          <div class="modal__corner modal__corner--br" :style="{ borderColor: accent.primary }"></div>

          <header class="modal__header" :style="{ color: accent.primary }">
            📜 套用预置模板 · {{ title }}
          </header>

          <div class="modal__body">
            <!-- 模板选择 -->
            <div class="form-item">
              <label class="form-label">① 选择模板</label>
              <div class="tpl-grid">
                <button
                  v-for="t in templates"
                  :key="t.key"
                  type="button"
                  class="tpl-card-mini"
                  :class="{ 'is-selected': selectedTemplateKey === t.key, 'is-disabled': templateApplying }"
                  :disabled="templateApplying"
                  @click="selectedTemplateKey = t.key"
                >
                  <div class="tcm-head">
                    <span class="tcm-icon">{{ t.icon }}</span>
                    <span class="tcm-name">{{ t.name }}</span>
                  </div>
                  <div class="tcm-tags" v-if="t.tags">
                    <span v-for="tag in t.tags" :key="tag" class="tcm-tag">#{{ tag }}</span>
                  </div>
                  <div class="tcm-count" v-if="t.count">{{ t.count }} 项</div>
                </button>
              </div>
              <div class="form-hint" v-if="templatePreview?.count">
                共 <strong>{{ templatePreview.count }}</strong> 项将被套用
              </div>
            </div>

            <!-- 模式选择 -->
            <div class="form-item" v-if="templatePreview">
              <label class="form-label">② 套用模式</label>
              <div class="mode-row">
                <label class="mode-card" :class="{ 'is-on': importMode === 'merge' }">
                  <input type="radio" v-model="importMode" value="merge" />
                  <div class="mc-title">合并模式 <span class="mc-tag rec">推荐</span></div>
                  <div class="mc-desc">保留现有项；同 key 覆盖（系统内置跳过），新 key 追加。</div>
                </label>
                <label class="mode-card" :class="{ 'is-on': importMode === 'replace' }">
                  <input type="radio" v-model="importMode" value="replace" />
                  <div class="mc-title">整体替换</div>
                  <div class="mc-desc">清空现有列表（保留系统内置项），完整使用模板内容替代。</div>
                </label>
              </div>
            </div>

            <!-- 预览 -->
            <div class="form-item" v-if="templatePreview">
              <label class="form-label">③ 模板预览</label>
              <div class="preview-wrap">
                <div class="preview-list">
                  <div
                    v-for="it in templatePreview.items.slice(0, 30)"
                    :key="it.key"
                    class="pv-item"
                    :style="{
                      borderColor: colorSwatch(it.color).border,
                      background: colorSwatch(it.color).bg,
                      color: colorSwatch(it.color).text,
                    }"
                    :title="it.desc"
                  >
                    <span class="pvi-label">{{ it.label }}</span>
                    <span class="pvi-key mono">{{ it.key }}</span>
                  </div>
                  <div class="pv-more" v-if="templatePreview.items.length > 30">
                    及另外 {{ templatePreview.items.length - 30 }} 项...
                  </div>
                </div>
              </div>
            </div>

            <!-- 日志 -->
            <div class="form-item" v-if="templateLog.length">
              <label class="form-label">套用日志</label>
              <div class="import-log">
                <div
                  v-for="(l, idx) in templateLog"
                  :key="idx"
                  class="log-line"
                  :class="'log-line--' + l.type"
                >
                  <span class="log-time">{{ l.time }}</span>
                  <span class="log-type">
                    {{ l.type === 'info' ? 'ℹ' : l.type === 'create' ? '✓+' : l.type === 'update' ? '✎' : l.type === 'skip' ? '↷' : '✕' }}
                  </span>
                  <span class="log-msg">{{ l.msg }}</span>
                </div>
              </div>
            </div>
          </div>

          <footer class="modal__footer">
            <button
              class="btn btn--ghost"
              :disabled="templateApplying"
              @click="closeTemplateModal"
            >{{ templateLog.length ? '完成，关闭' : '取消' }}</button>
            <button
              class="btn btn--primary"
              :style="{ background: accent.primary, boxShadow: `0 4px 12px ${accent.glow}` }"
              :disabled="templateApplying || !selectedTemplateKey"
              @click="applyTemplate"
            >
              <span v-if="templateApplying" class="loading-dots"><span></span><span></span><span></span>套用中...</span>
              <span v-else>📜 一键套用模板</span>
            </button>
          </footer>
        </div>
      </div>
    </Teleport>

    <!-- Modal：新增/编辑 -->
    <Teleport to="body">
      <div class="modal-mask" v-if="modalOpen" @click.self="closeModal">
        <div class="modal" :style="{ borderColor: accent.primary }">
          <!-- 角装饰 -->
          <div class="modal__corner modal__corner--tl" :style="{ borderColor: accent.primary }"></div>
          <div class="modal__corner modal__corner--tr" :style="{ borderColor: accent.primary }"></div>
          <div class="modal__corner modal__corner--bl" :style="{ borderColor: accent.primary }"></div>
          <div class="modal__corner modal__corner--br" :style="{ borderColor: accent.primary }"></div>

          <header class="modal__header" :style="{ color: accent.primary }">
            {{ editingIndex >= 0 ? '编辑选项' : '新增选项' }}
          </header>

          <div class="modal__body">
            <!-- key -->
            <div class="form-item">
              <label class="form-label">
                英文标识
                <span class="required">*</span>
              </label>
              <input
                class="form-input"
                v-model="form.key"
                :class="{ 'has-error': formErrors.key }"
                :disabled="editingIndex >= 0 && isReadOnly(form.key)"
                :placeholder="keyPlaceholder"
                type="text"
              />
              <div class="form-error" v-if="formErrors.key">{{ formErrors.key }}</div>
              <div class="form-hint" v-else>
                {{ editingIndex >= 0 ? '编辑已有项时无法修改 key' : '创建后不可修改，建议使用英文大写或 snake_case' }}
              </div>
            </div>

            <!-- label -->
            <div class="form-item">
              <label class="form-label">
                显示名称
                <span class="required">*</span>
              </label>
              <input
                class="form-input"
                v-model="form.label"
                :class="{ 'has-error': formErrors.label }"
                placeholder="中文名称，如：超凡势力 / 活跃 / 灵境"
                type="text"
              />
              <div class="form-error" v-if="formErrors.label">{{ formErrors.label }}</div>
            </div>

            <!-- color -->
            <div class="form-item">
              <label class="form-label">显示颜色</label>
              <div class="color-grid">
                <button
                  v-for="opt in COLOR_OPTIONS"
                  :key="opt.key"
                  type="button"
                  class="color-chip"
                  :class="{ 'is-selected': form.color === opt.key }"
                  :style="{
                    borderColor: form.color === opt.key ? opt.sample : 'var(--border-color)',
                    background: CHOICE_COLORS[opt.key].bg,
                    color: opt.sample,
                    boxShadow: form.color === opt.key ? `0 0 12px ${CHOICE_COLORS[opt.key].border}` : 'none',
                  }"
                  @click="form.color = opt.key"
                >
                  <span class="chip-dot" :style="{ background: opt.sample }"></span>
                  {{ opt.label }}
                </button>
              </div>
            </div>

            <!-- weight -->
            <div class="form-item form-item--row">
              <div class="form-row-left">
                <label class="form-label">
                  排序权重
                  <span class="required">*</span>
                </label>
                <input
                  class="form-input"
                  v-model.number="form.weight"
                  :class="{ 'has-error': formErrors.weight }"
                  placeholder="1 - 999，越小越靠前"
                  type="number"
                  min="1"
                  max="999"
                />
                <div class="form-error" v-if="formErrors.weight">{{ formErrors.weight }}</div>
                <div class="form-hint" v-else>建议 1-99。数值越小，在下拉和列表中越靠前。</div>
              </div>
            </div>

            <!-- desc -->
            <div class="form-item">
